for _,g in cap.sort_values(['Branch_ID','Shift','Date']).groupby(['Branch_ID','Shift']): rec_ok &= np.allclose(g.Opening_Backlog.iloc[1:],g.Closing_Backlog.iloc[:-1],atol=.02)
chk('backlog_recursion',bool(rec_ok)); chk('outage_overlap_fields',{'System_Downtime_Minutes'}.issubset(cap.columns)); chk('analyst_integrity',analysts.Analyst_ID.is_unique and df.Analyst_ID.isin(analysts.Analyst_ID).all())
