defcols=[c for c in df if c.endswith('_Defect')]; chk('defect_opportunities',len(defcols)==6 and np.array_equal(df.Defect_Count.values,df[defcols].sum(axis=1).values)); chk('dpmo_inputs',len(defcols)>0)
chk('cost_of_quality',np.allclose(df.Total_Cost_of_Quality,df.Total_Prevention_Cost+df.Total_Appraisal_Cost+df.Total_COPQ)); chk('copq_reconciliation',np.allclose(df.Total_COPQ,df.Total_Internal_Failure_Cost+df.Total_External_Failure_Cost)); chk('required_control_excluded_from_copq',np.allclose(df.Total_Appraisal_Cost,df.Required_Manual_Review_Cost))
