# docs and links
md=list(ROOT.rglob('*.md')); chk('documentation',len(md)>=15,f'{len(md)} markdown files'); text='\n'.join(p.read_text(errors='ignore') for p in md); chk('synthetic_disclosure','synthetic' in text.lower()); bad_placeholders=re.findall(r'\b(TODO|TBD|LOREM IPSUM|COMING SOON)\b',text,re.I); chk('no_placeholders',not bad_placeholders,str(bad_placeholders[:5])); chk('privacy_no_real_customer_names',not re.search(r'\b(customer name|account number)\s*:',text,re.I)); chk('no_credentials',not re.search(r'(api[_-]?key|password|secret)\s*[:=]\s*["\'][^"\']+',text,re.I)); chk('python_syntax',subprocess.run([sys.executable,'-m','compileall','-q',str(ROOT/'src'),str(ROOT/'scripts')]).returncode==0); chk('sql_coverage',len(list((ROOT/'sql').glob('*.sql')))>=5); chk('ci_wiring',(ROOT/'.github/workflows/ci.yml').exists()); manifest=json.loads((ROOT/'results'/'generation_manifest.json').read_text()); chk('output_hashes',len(manifest.get('output_hashes',{}))>=6); chk('repository_hygiene',(ROOT/'.gitignore').exists()); chk('readme_metrics',(ROOT/'README.md').exists() and 'First Pass Yield' in (ROOT/'README.md').read_text()); chk('operational_definitions',(ROOT/'docs/operational-definitions.md').exists()); chk('causal_map',(ROOT/'docs/data-generating-process.md').exists()); chk('control_phase',(ROOT/'results'/'control_results.json').exists()); chk('pilot_phase',(ROOT/'results'/'pilot_results.json').exists()); chk('fmea',(ROOT/'results'/'fmea.csv').exists()); chk('hypothesis_tests',(ROOT/'results'/'hypothesis_tests.json').exists())
overall=all(c['status']=='PASS' for c in checks); report={'passed':sum(c['status']=='PASS' for c in checks),'total':len(checks),'overall':'PASS' if overall else 'FAIL','checks':checks}; (ROOT/'results'/'qa_report.json').write_text(json.dumps(report,indent=2)); print(json.dumps({'passed':report['passed'],'total':report['total'],'overall':report['overall'],'failures':[c for c in checks if c['status']=='FAIL']},indent=2)); sys.exit(0 if overall else 1)
